#!/usr/bin/env python3
"""Apply PR #38 probe, matrix, and documentation hardening."""

from __future__ import annotations

import base64
import json
from pathlib import Path

ROOT = Path.cwd()
PROBE_B64 = ""
VALIDATOR_B64 = ""


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one match, found {count}")
    return text.replace(old, new, 1)


(ROOT / "native/scripts/probe_client_capabilities.py").write_bytes(
    base64.b64decode(PROBE_B64)
)
(ROOT / "native/scripts/validate_client_capability_matrix.py").write_bytes(
    base64.b64decode(VALIDATOR_B64)
)

matrix_path = ROOT / "native/contracts/client-capability-matrix-v1.json"
matrix = json.loads(matrix_path.read_text(encoding="utf-8"))
matrix["externalRuntimeWriteAdmission"] = (
    "disabled_until_daemon_trusted_receipt_verifier"
)
for platform in matrix["platforms"]:
    version = platform["versions"][0]
    version["mutationEligible"] = False
    if platform["id"] == "claude_code":
        for source in platform["sources"]:
            if source.get("url") == (
                "https://registry.npmjs.org/@anthropic-ai/claude-code/latest"
            ):
                source["url"] = (
                    "https://registry.npmjs.org/@anthropic-ai/claude-code/2.1.223"
                )
        version["npmArtifact"] = {
            "tarball": (
                "https://registry.npmjs.org/@anthropic-ai/claude-code/-/"
                "claude-code-2.1.223.tgz"
            ),
            "shasum": "a05d73e01e71d5a68708d30421b9945b41a15641",
            "integrity": (
                "sha512-t6la5i6TP8p/zf6QlZjwzpMKM3kCty6aGRv6opeOnMVnJRcVuchPWSPgcdZZ"
                "dvE82Alk4xbJ83XQXGOj6F4mlA=="
            ),
        }
    if platform["id"] == "generic_mcp_host":
        platform["capabilities"]["writePolicy"] = (
            "read_only_until_daemon_trusted_probe_receipt"
        )
        version["releaseChannel"] = "locked_conformance_evidence_read_only"
matrix_path.write_text(json.dumps(matrix, indent=2) + "\n", encoding="utf-8")

docs_path = ROOT / "docs/testing/CLIENT-CAPABILITY-MATRIX.md"
docs = docs_path.read_text(encoding="utf-8")
docs = replace_once(
    docs,
    (
        "Status: Phase 5 implementation contract for P5-002 through P5-006.  "
        "This document describes the mechanisms exposed by supported client "
        "surfaces and the exact evidence required before any external client "
        "can receive a read-write Soleaux workspace binding.\n"
    ),
    (
        "Status: Phase 5 implementation contract for P5-002 through P5-006.  "
        "This document describes supported client mechanisms and evidence. "
        "No external client receives a read-write Soleaux workspace binding "
        "until a daemon-trusted admission receipt verifier is implemented.\n"
    ),
    "replace external write premise",
)
docs = replace_once(
    docs,
    (
        "The machine-readable authority is "
        "[`native/contracts/client-capability-matrix-v1.json`]"
        "(../../native/contracts/client-capability-matrix-v1.json).  The daemon "
        "embeds that file, publishes its SHA-256 digest in registry status, and "
        "requires a probe to bind to the exact digest, platform, client version, "
        "required signals, and evidence hash.  Unknown versions, documentation-only "
        "surfaces, stale digests, malformed evidence, and platform/kind mismatches "
        "remain read-only.\n"
    ),
    (
        "The machine-readable authority is "
        "[`native/contracts/client-capability-matrix-v1.json`]"
        "(../../native/contracts/client-capability-matrix-v1.json).  The daemon "
        "embeds that file and publishes its SHA-256 digest in registry status. "
        "Probe reports are archival evidence, not runtime authorization. Unknown "
        "versions, documentation-only surfaces, stale or malformed evidence, and "
        "all external clients remain read-only.\n"
    ),
    "replace runtime authorization description",
)
docs = replace_once(
    docs,
    (
        "| Generic MCP host fixture | `mcp-2025-11-25` | P5-006 | Native "
        "initialize, tools/list, context.compile, registry registration, "
        "read-write binding, and twelve-tool-ceiling smokes | Allowed only with "
        "exact matrix-bound probe evidence |\n"
    ),
    (
        "| Generic MCP host fixture | `mcp-2025-11-25` | P5-006 | Native "
        "initialize, tools/list, context.compile, registry registration, "
        "binding rejection, and twelve-tool-ceiling smokes | Denied; conformance "
        "evidence is archival until trusted receipt admission exists |\n"
    ),
    "replace generic host safety row",
)
start = docs.index("The generic MCP fixture is the only mutation-eligible entry.")
end = docs.index("\n## Probe and evidence files", start)
replacement = """No external matrix entry is mutation eligible. The generic MCP fixture proves the
locked conformance surface against compiled Soleaux binaries, including initialization,
the exact twelve-tool profile, Context Packet V2, registry registration, and rejection
of caller-self-attested read-write admission. Its compact registration proof stays below
the IPC field limit, while full command output remains in the archival report.

The only current write-capable client path is the exact internal Soleaux CLI identity.
External write admission requires a future daemon-trusted, cryptographically bound receipt
verifier and a separately reviewed lifecycle oracle; a caller-computed hash is never
accepted as authorization.
"""
docs = docs[:start] + replacement + docs[end:]
docs = replace_once(
    docs,
    (
        "- `native/scripts/probe_client_capabilities.py` executes bounded argv-only "
        "binary probes and emits registration-ready evidence.\n"
    ),
    (
        "- `native/scripts/probe_client_capabilities.py` streams and hashes bounded "
        "argv-only output, applies signal-specific oracles, and separates compact "
        "registration evidence from archival output.\n"
    ),
    "update probe description",
)
docs = replace_once(
    docs,
    (
        "- `native/scripts/p5_client_matrix_smoke.py` proves the exact generic-host "
        "registration and read-write binding while vendor clients remain read-only.\n"
    ),
    (
        "- `native/scripts/p5_client_matrix_smoke.py` proves external read-write "
        "rejection, internal CLI write access, heartbeat revalidation, and the "
        "locked registry/matrix invariants.\n"
    ),
    "update smoke description",
)
docs = replace_once(
    docs,
    (
        "5. Keep `mutationEligible=false` unless authenticated lifecycle behavior "
        "has a task-specific oracle and exact evidence.\n"
    ),
    (
        "5. Keep `mutationEligible=false`; enabling external writes additionally "
        "requires a daemon-trusted cryptographic receipt verifier and an "
        "authenticated task-specific lifecycle oracle.\n"
    ),
    "strengthen update rule",
)
docs_path.write_text(docs, encoding="utf-8")

print("probe and matrix track applied")
